    "SOR-2026-08-P077-S091",
    "SOR-2026-08-P074-S085"
  ],
  "conditions_and_exceptions": "El pesaje oficial se programa un día antes de la competencia a las 16:00 hora local, durando entre 30 y 60 minutos, y pasar el pesaje oficial es responsabilidad exclusiva del atleta [SOR-2026-08-P077-S091]. Solo se considera el peso registrado en la báscula oficial para la categoría del atleta [SOR-2026-08-P077-S091]. El acceso a las salas de pesaje está estrictamente restringido por género [SOR-2026-08-P077-S091]. La fotografía o filmación está estrictamente prohibida en el área de pesaje [SOR-2026-08-P077-S091].",
  "extended_analysis": "No aplica",
  "limitations": "Los pasajes entregados no contienen detalles específicos sobre todas las posibles variaciones de horarios aprobados por la IJF Sport Commission para eventos que no sean los estándar.",
  "answerability": "RESPALDADA",
  "evidence_quotes": [
    {
      "passage_id": "SOR-2026-08-P077-S091",
      "quote": "For IJF events, the official weigh-in is scheduled one day before the competition at 16:00 local time.",
      "supports": "Programación del pesaje oficial"
    },
    {
      "passage_id": "SOR-2026-08-P077-S091",
      "quote": "The official weigh-in lasts between 30 and 60 minutes; the exact times will be published in the event outlines.",
      "supports": "Duración del pesaje oficial"
    },
    {
      "passage_id": "SOR-2026-08-P077-S091",
      "quote": "Passing the official weigh-in is the responsibility of the athlete.",
      "supports": "Responsabilidad del atleta"
    },
    {
      "passage_id": "SOR-2026-08-P077-S091",
      "quote": "Photography or filming is strictly prohibited in the weigh-in area.",
      "supports": "Prohibición de fotografía o filmación"
    }
  ],
  "evidence_conflicts": []
}

